import SwiftUI

struct ChecklistManagementView: View {
    @Environment(AppEnvironment.self) private var environment
    let access:BabyAccess
    @State private var items:[ChecklistItem]=[];@State private var editing:ChecklistItem?;@State private var adding=false;@State private var error:String?
    var body:some View{List{ForEach(items){item in Button{editing=item}label:{HStack{Image(systemName:item.symbol).foregroundStyle(TrackingCategory.other.style.main).frame(width:28);Text(item.title);Spacer();Text(item.isActive ? "Active":"Inactive").font(.caption).foregroundStyle(BabyLogTheme.mutedText);Image(systemName:"chevron.right").foregroundStyle(BabyLogTheme.mutedText).accessibilityHidden(true)}}.buttonStyle(.plain).swipeActions{Button(item.isActive ? "Remove":"Restore"){Task{await toggle(item)}}.tint(item.isActive ? .red : TrackingCategory.diaper.style.main)}}.onMove{source,destination in var changed=items;changed.move(fromOffsets:source,toOffset:destination);items=changed;Task{try? await environment.checklistRepository.reorder(changed)}}} .navigationTitle("Daily Checklist").toolbar{ToolbarItem(placement:.topBarTrailing){Button{adding=true}label:{Image(systemName:"plus")}.accessibilityLabel("Add checklist item")};ToolbarItem(placement:.topBarLeading){EditButton()}}.task{await observe()}.sheet(isPresented:$adding){ChecklistItemEditorSheet(babyID:access.baby.id,userID:access.membership.userID,sortOrder:items.count){try await environment.checklistRepository.createItem($0)}}.sheet(item:$editing){item in ChecklistItemEditorSheet(item:item,babyID:access.baby.id,userID:access.membership.userID,sortOrder:item.sortOrder){try await environment.checklistRepository.updateItem($0)}}.alert("Couldn’t Update",isPresented:Binding(get:{error != nil},set:{if !$0{error=nil}})){Button("OK",role:.cancel){}}message:{Text(error ?? "")}}
    private func observe()async{do{for try await value in environment.checklistRepository.observeItems(babyID:access.baby.id,includeInactive:true){items=value}}catch{self.error="Checklist couldn’t refresh."}}
    private func toggle(_ item:ChecklistItem)async{do{var changed=item;changed.isActive.toggle();try await environment.checklistRepository.updateItem(changed)}catch{self.error="Checklist item couldn’t be updated."}}
}
